import { Table, TableNameColumn, StringColumn, ReferenceColumn } from '../../db'

export const sys_ui_form = Table({
    name: 'sys_ui_form',
    extends: 'sys_metadata',
    schema: {
        name: TableNameColumn({ mandatory: false, label: 'Table', read_only: false, active: true, maxLength: 80 }),
        roles: StringColumn({
            mandatory: false,
            label: 'Roles',
            read_only: false,
            active: true,
            maxLength: 40,
            dropdown: 'none',
        }),
        sys_overrides: ReferenceColumn({
            mandatory: false,
            label: 'Overrides',
            read_only: false,
            active: true,
            maxLength: 32,
            referenceTable: 'sys_ui_form',
        }),
        sys_user: ReferenceColumn({
            mandatory: false,
            label: 'Sys user',
            read_only: false,
            active: true,
            maxLength: 32,
            referenceTable: 'sys_user',
        }),
        view: ReferenceColumn({
            mandatory: false,
            label: 'View',
            read_only: false,
            active: true,
            maxLength: 32,
            referenceTable: 'sys_ui_view',
        }),
        view_name: StringColumn({
            mandatory: false,
            label: 'View name',
            read_only: false,
            active: true,
            maxLength: 40,
            dropdown: 'none',
        }),
    },
})
